INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(128588, 'ruRU', '', 'Знаешь, мне бы, наверное, пошёл зелёный...', 24330),
(128589, 'ruRU', '', 'Копьё из огня скверны сейчас бы очень пригодилось...', 24330),
(128613, 'ruRU', '', 'Если это было только отвлечением, то где главная атака? Нужно спросить у Авианы. Она будет знать!', 24330),
(128621, 'ruRU', '', 'Даже после возвращения Канретада эти оккультисты остаются верны Легиону. Мы не можем позволить им вернуть контроль над Перевалом Огня Скверны. Сократи их число и поглоти их источники силы!', 24330),
(128622, 'ruRU', '', 'Какая демонстрация силы! Готов поспорить, эти оккультисты уже жалеют о союзе с нашим врагом!', 24330),
(128623, 'ruRU', '', 'Перевал Огня Скверны кишит оккультистами, верными Пылающему Легиону. Мы не можем позволить им закрепиться!', 24330),
(128624, 'ruRU', '', 'Даже после смерти своего лидера эти осквернённые ловцы не остановятся! Возьми эту мазь из мана-корня и нанеси её на любых раненых животных, которых увидишь. Спаси как можно больше!', 24330),
(128626, 'ruRU', '', 'Ты истинный защитник природы. Прими мою благодарность.', 24330),
(128627, 'ruRU', '', 'Мои избранники дарят дар жизни, защитник. Прими их награду и продолжай бой!', 24330),
(128628, 'ruRU', '', 'Защитники, Легион пытается проникнуть в Громовой Тотем снизу. Помогите отбросить их!', 24330),
(128630, 'ruRU', '', 'Один из геомантов Наваррога запечатывает тоннели, чтобы остановить поток врагов Легиона. Защищай его любой ценой!', 24330),
(128631, 'ruRU', '', 'Аргх!', 24330),
(128632, 'ruRU', '', 'Герои... разберитесь с этим... исчадием...', 24330),
(128633, 'ruRU', '', 'Хорошая работа, герои. Хоть запечатаны только два тоннеля, каждая малость помогает.', 24330),
(128635, 'ruRU', '', 'Понятно. Герои, давайте двигаться к точке встречи.', 24330),
(128636, 'ruRU', '', 'Берегись!', 24330),
(128637, 'ruRU', '', 'Нам нужно продолжать двигаться!', 24330),
(128638, 'ruRU', '', 'Как только окажешься на борту, спаси всех пленников, кого сможешь. Когда мои люди будут в безопасности, установи эти взрывчатки и покинь корабль... быстро!', 24330),
(128642, 'ruRU', '', 'Осквернённые ловцы применяют свою искажённую магию на местной дикой природе. Возьми эту мазь из мана-корня и нанеси её на любых раненых животных, которых увидишь. Поспеши, пока порча не укоренилась!', 24330),
(128644, 'ruRU', '', 'Поспешите, герои. Лазану нужна ваша помощь!', 24330),
(128647, 'ruRU', '', 'Заражение скверной снова нашло путь к Пристани Мёртвого Леса, Верховный жрец. Нам нужно сдержать эту болезнь, прежде чем она заразит материк.', 24330),
(128648, 'ruRU', '', 'Ужасное заражение охватило Пристань Мёртвого Леса. Гарпии, кишащие на острове, являются носителями. Их порчу нельзя допустить распространиться!', 24330),
(128649, 'ruRU', '', 'Блестящая работа! Похоже, заражение сдержано.', 24330),
(128652, 'ruRU', '', 'Встретимся дальше впереди.', 24330),
(128670, 'ruRU', '', 'Не уверен, что это сработает, но стоит попробовать... Отойди!', 24330),
(128672, 'ruRU', '', 'Шал\'дорай были изолированы на протяжении столь многих поколений. Нам трудно открыть разум новым способам мышления.', 24330),
(128674, 'ruRU', '', 'Если бы мои старейшины узнали, что я общаюсь с чужаком, меня бы изгнали... Или хуже.', 24330),
(128676, 'ruRU', '', 'Авиана! Твои дети нуждаются в тебе. Друидов Когтя истребляют руками Легиона!', 24330),
(128678, 'ruRU', '', 'Я всегда находила магию чудесной во всех её формах. Теперь, когда щит рассеялся, я не могу дождаться, чтобы овладеть ею целиком!', 24330),
(128681, 'ruRU', '', 'Подумать только, мои братья и сёстры погибли из-за "отвлечения"... Я этого не потерплю!', 24330),
(128684, 'ruRU', '', 'Авиана, твои птицы приносят вести со всего Азерота. Прошу, помоги нам найти цель демонов! Мы должны отомстить за наших павших сородичей!', 24330),
(128686, 'ruRU', '', 'Ох! Я наткнулась на него в Тель\'аноре, пойманного в путы гарпии, без единой нитки одежды! Ха!\n\nГарпия была так занята спором с банши о том, кто первой будет с ним играть, что они совсем меня не заметили.\n\nОн выглядел ужасно неловко, так что я вмешалась. А дальше - уже история!', 24330),
(128689, 'ruRU', '', 'Сигнатуры угроз нейтрализованы. Защита объекта на уровне 74.39 процента. Ремонт в процессе.', 24330),
(128690, 'ruRU', '', 'Субъект: Азерот. Обнаружена незначительная аритмия, но жизненные показатели в пределах допустимых параметров. Отчёты об инцидентах обновлены.', 24330),
(128699, 'ruRU', '', 'Те, кто причиняет вред моим детям, заплатят за это!', 24330),
(128700, 'ruRU', '', 'Авиана!', 24330),
(128703, 'ruRU', '', 'Ого... Авиана...', 24330),
(128704, 'ruRU', '', 'Нельзя терять времени, архидруид! Я готова колоть демонов!', 24330),
(128732, 'ruRU', '', 'Помогите мне! Скорее!', 24330),
(128734, 'ruRU', '', 'Давай, идём! Нам нужно спасти Голдрина!', 24330);
